Lemma entries_nowrap_lazy_interior : forall (a n : word),
  entry_nowrap (a, n) -> entries_nowrap (lazy_interior a n).
Proof.
  intros a n H p Hp. pose proof (lazy_interior_sub a n p H Hp). unfold entry_nowrap in *. lia.
Qed.

